<?php
require __DIR__.'/inc/v11.php';auth();v11_require();require_once __DIR__.'/inc/moving-file.php';
$p=db();$page=max(1,min(100000,(int)($_GET['page']??1)));$perPage=50;$search=$_GET['q']??'';if(!is_string($search))$search='';$search=mb_substr(trim($search),0,100);
$where=" WHERE q.status IN ('accepted','approved','completed') AND NOT EXISTS(SELECT 1 FROM quote_archives qa WHERE qa.quote_id=q.id) AND NOT EXISTS(SELECT 1 FROM moving_quote_meta mm WHERE mm.quote_id=q.id AND JSON_EXTRACT(mm.payload,'$.revision_effective_child_id')>0)";$params=[];
if($search!==''){$where.=' AND (q.quote_no LIKE ? OR c.name LIKE ? OR q.origin LIKE ? OR q.destination LIKE ?)';$params=array_fill(0,4,'%'.$search.'%');}
$s=$p->prepare('SELECT COUNT(*) FROM quotes q JOIN customers c ON c.id=q.customer_id'.$where);$s->execute($params);$count=(int)$s->fetchColumn();$pages=max(1,(int)ceil($count/$perPage));$page=min($page,$pages);
$s=$p->prepare('SELECT q.id FROM quotes q JOIN customers c ON c.id=q.customer_id'.$where.' ORDER BY q.id DESC LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage));$s->execute($params);$rows=[];$errors=[];
foreach($s->fetchAll(PDO::FETCH_COLUMN) as $id){try{$rows[]=ekMoveContext($p,(int)$id);}catch(Throwable $e){$errors[]='Teklif #'.(int)$id.': '.$e->getMessage();}}
require __DIR__.'/inc/layout.php';top('Taşınma Dosyaları');
?>
<link rel="stylesheet" href="assets/v11.css?v=36001"><div class="v11-head"><h1>Taşınma Dosyaları</h1><p>Onaylı her taşımanın güncel teklifi ve mevcut operasyon planı. Tarihsel revizyonlar ayrı dosya oluşturmaz.</p></div>
<section class="v11-card"><form method="get" class="v11-fields"><label>Müşteri, teklif veya güzergâh<input name="q" value="<?=h($search)?>" maxlength="100"></label><button type="submit">Ara</button><a href="moving-files.php">Temizle</a></form><p><?=$count?> dosya · Sayfa <?=$page?> / <?=$pages?></p>
<?php foreach($errors as $message):?><p role="alert"><?=h($message)?></p><?php endforeach;?><div class="v11-table"><table><thead><tr><th>Dosya</th><th>Müşteri</th><th>Güzergâh</th><th>Yükleme</th><th>Durum</th></tr></thead><tbody><?php foreach($rows as $ctx):?><tr><td><a href="move-file.php?id=<?=(int)$ctx['effective_id']?>">TD-<?=str_pad((string)$ctx['root_id'],6,'0',STR_PAD_LEFT)?></a><div><?=h($ctx['quote']['quote_no'])?></div></td><td><?=h($ctx['quote']['name'])?></td><td><?=h($ctx['quote']['origin'].' → '.$ctx['quote']['destination'])?></td><td><?=h($ctx['move']?v11_date($ctx['move']['loading_date']):'Planlanmadı')?></td><td><?=h($ctx['move']?ekMoveStatus($ctx['move']['status']):'Plan bekliyor')?></td></tr><?php endforeach;?><?php if(!$rows&&!$errors):?><tr><td colspan="5">Dosya bulunamadı.</td></tr><?php endif;?></tbody></table></div>
<nav aria-label="Dosya sayfaları"><?php foreach(['Önceki'=>$page-1,'Sonraki'=>$page+1] as $label=>$target):if($target<1||$target>$pages)continue;?><a href="moving-files.php?<?=h(http_build_query(['q'=>$search,'page'=>$target]))?>"><?=h($label)?></a> <?php endforeach;?></nav></section><?php bottom(); ?>
